
'use strict';
const supportBaseRender=render;
render=function(){supportBaseRender();if(publicPage)return;const nav=document.querySelector('.side-nav');if(nav&&!nav.querySelector('[data-support-link]'))nav.insertAdjacentHTML('beforeend',`<a class="support-dashboard-link" data-support-link href="/support.html">${icon('help')}${role==='admin'?'الدعم والتذاكر':'الدعم والمساعدة'}</a>`);if(nav&&role==='admin'&&!nav.querySelector('[data-marketing-admin]'))nav.insertAdjacentHTML('beforeend',`<a class="support-dashboard-link" data-marketing-admin href="/marketing.html">${icon('link')}<span>تسويق واتساب</span></a>`);if(nav&&role==='owner'&&!nav.querySelector('[data-whatsapp-marketing]'))nav.insertAdjacentHTML('beforeend',`<button type="button" class="support-dashboard-link whatsapp-marketing-locked" data-whatsapp-marketing disabled aria-label="تسويق واتساب، مقفل، قريبًا" title="قريبًا: ربط حساب النشاط بميتا وإدارة القوالب والحملات والتذكيرات والعروض والمكافآت. يدفع النشاط تكلفة الرسائل عبر حسابه."><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><rect x="5" y="10" width="14" height="11" rx="3"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/><path d="M12 14v3"/></svg><span>تسويق واتساب</span><small>قريبًا</small></button>`);if(role==='client')document.querySelector('.workspace')?.insertAdjacentHTML('beforeend','<div class="support-customer-link"><a href="/support.html">الدعم والمساعدة</a></div>');};
render();
const whatsappMarketingStyle=document.createElement('style');whatsappMarketingStyle.textContent='.whatsapp-marketing-locked{width:100%;font-family:inherit;cursor:not-allowed;opacity:.62;text-align:right;margin-top:8px}.whatsapp-marketing-locked small{margin-inline-start:auto;padding:3px 8px;border-radius:20px;background:#ffffff12;font-size:10px;white-space:nowrap}.whatsapp-marketing-locked:hover{background:#ffffff04}';document.head.append(whatsappMarketingStyle);